    blogMuglaDatcaTitle: "Datça Peninsula",
    blogMuglaDatcaDesc: "Unspoiled paradise known for honey and almonds. Features ancient Knidos and some of Turkey's most pristine beaches. Perfect for those seeking tranquility.",
