    blogMuglaMapTitle: "Muğla Region Map",
    blogMuglaMapDesc: "Muğla Province covers a vast area from Bodrum in the west to Fethiye in the east, with Dalaman Airport centrally located.",
    blogMuglaFaq1Q: "Which airport should I use for Bodrum?",
    blogMuglaFaq1A: "Milas-Bodrum Airport (BJV) is closest to Bodrum (36km). Dalaman Airport (DLM) is 95km away but offers more flight options.",
    blogMuglaFaq2Q: "Can I visit multiple towns in one transfer?",
    blogMuglaFaq2A: "Yes! We offer multi-stop transfers. Popular routes include Fethiye-Ölüdeniz or Marmaris-Dalyan combinations.",
    blogMuglaFaq3Q: "How long is the transfer from Dalaman to Bodrum?",
