    blogTaxiFaq4Q: "Sprechen türkische Fahrer Englisch?",
    blogTaxiFaq4A: "Die Englischkenntnisse variieren stark. Fahrer in touristischen Gebieten wie Istanbul, Antalya und Bodrum können grundlegendes Englisch haben. Privattransfer-Fahrer sprechen typischerweise fließend Englisch.",
    blogTaxiFaq5Q: "Was passiert, wenn mein Flug Verspätung hat?",
    blogTaxiFaq5A: "Bei Privattransfer überwacht Ihr Fahrer Ihren Flug und passt entsprechend an - ohne Aufpreis. Bei regulärem Transport nehmen Sie einfach, was bei Ankunft verfügbar ist.",
