    blogWorthItDesc: "Türkiye'de özel transferlerin gerçek maliyet ve faydalarını analiz ediyoruz.",
    blogWorthItH1: "Türkiye'de Özel Transfer Değer mi?",
    blogWorthItIntro: "Türkiye'de özel transferlerin gerçek maliyet ve faydalarını analiz ediyoruz.",
    blogWorthItFaqTitle: "Sıkça Sorulan Sorular",
    blogWorthItFaq1Q: "Özel transfer ekstra maliyete gerçekten değer mi?",
    blogWorthItFaq1A: "Çoğu gezgin için evet. Tasarruf edilen zaman, konfor, güvenlik ve özellikle başkalarıyla seyahat edildiğinde değer önerisi güçlüdür. 4 kişilik bir aile, kişi başı ayrı normal ulaşım seçenekleriyle aşağı yukarı aynı ücreti öder.",
    blogWorthItFaq2Q: "Özel transfer ne zaman DEĞMEZİZ?",
    blogWorthItFaq2A: "Gündüz kısa mesafelerde bütçeli yalnız gezginler normal ulaşımı daha ekonomik bulabilir. Ancak gece varışları, aileler veya gruplar için özel transfer neredeyse her zaman daha iyi değer sunar.",
    blogWorthItFaq3Q: "Özel transfer ne kadar daha pahalı?",
    blogWorthItFaq3A: "Özel transferler genellikle normal ulaşım tarifesinin 2-3 katına mal olur. Ancak bu karşılama, sabit fiyat, premium araç ve profesyonel şoför içerir. 2+ yolcu için kişi başı maliyet karşılaştırılabilir hale gelir.",
    blogWorthItFaq4Q: "Özel transferi normal ulaşımdan daha iyi yapan nedir?",
    blogWorthItFaq4A: "Temel avantajlar: beklemeden ön rezervasyon, sürpriz olmadan sabit fiyat, karşılama hizmeti, İngilizce konuşan profesyonel şoför, premium araç, uçuş takibi ve kapıdan kapıya hizmet.",
    blogWorthItFaq5Q: "Özel transferi online rezerve etmek güvenli mi?",
    blogWorthItFaq5A: "Evet, saygın şirketlerle. Dikkat edin: yorumlar, şeffaf fiyatlar, profesyonel web sitesi, WhatsApp iletişimi ve almadan önce şoför detaylarının onayı.",
    blogWorthItFaq6Q: "Özel transfer büyük grupları alabilir mi?",
    blogWorthItFaq6A: "Evet! Sedanlardan (3 kişiye kadar) minivanlara (8'e kadar) ve minibüslere (16'ya kadar) araçlar sunuyoruz. Büyük gruplar genellikle özel transferle kişi başına en iyi değeri alır.",
    blogDubaiTitle: "Dubai Havalimanı Transfer Rehberi 2025 | Fiyatlar, Seçenekler ve İpuçları",
    blogDubaiDesc: "Dubai Havalimanı transferleri için tam rehber.",
    blogDubaiH1: "Dubai Havalimanı Transfer Rehberi",
    blogDubaiIntro: "Dubai Havalimanından otelinize ulaşım hakkında her şey.",
    blogCyprusTitle: "Kıbrıs Havalimanı Transfer Rehberi 2025 | Larnaka, Baf, Ercan",
    blogCyprusDesc: "Kıbrıs havalimanı transferleri için tam rehber.",
    blogCyprusH1: "Kıbrıs Havalimanı Transfer Rehberi",
    blogCyprusIntro: "Kıbrıs havalimanı transferleri hakkında her şey.",
    blogCyprusFaq1Q: "Kıbrıs'ta kaç havalimanı var?",
    blogCyprusFaq1A: "Kıbrıs'ta iki ana havalimanı var: Larnaka (LCA) ve Baf (PFO). Kuzey Kıbrıs'ta Ercan Havalimanı (ECN) hizmet vermektedir.",
    blogCyprusFaq2Q: "Larnaka Havalimanı'ndan Limasol'a ne kadar sürer?",
    blogCyprusFaq2A: "Larnaka Havalimanı'ndan Limasol'a özel transfer yaklaşık 45-55 dakika sürer. Mesafe yaklaşık 70 km.",
    blogCyprusFaq3Q: "Baf Havalimanı'ndan otellere en iyi ulaşım yolu nedir?",
    blogCyprusFaq3A: "Baf Havalimanı'ndan özel VIP transfer en uygun seçenektir. Şoförünüz doğrudan otelinize götürür.",
    blogCyprusFaq4Q: "Kıbrıs'ta havalimanı transferi ne kadar?",
    blogCyprusFaq4A: "Larnaka'dan özel transferler Larnaka şehrine €35-45, Limasol'a €60-75 ve Baf'a €90-110'dan başlar.",
    blogCyprusFaq5Q: "Kıbrıs havalimanlarından toplu taşıma var mı?",
    blogCyprusFaq5A: "Evet, ancak sınırlı. Larnaka'da bazı otobüs hizmetleri var ama tüm destinasyonları kapsamıyor. Özel transfer daha güvenilir.",
    blogCyprusFaq6Q: "Larnaka'dan Kuzey Kıbrıs'a transfer rezervasyonu yapabilir miyim?",
    blogCyprusFaq6A: "Evet, Girne ve Gazimağusa dahil Kuzey Kıbrıs'a transferler sunuyoruz. Sınır geçişi yaklaşık 15-20 dakika sürer.",
