    blogWorthItFaqTitle: "Часті запитання",
    blogWorthItFaq1Q: "Чи дійсно приватний трансфер вартий додаткових коштів?",
    blogWorthItFaq1A: "Для більшості мандрівників так. Якщо врахувати заощаджений час, комфорт, безпеку і особливо подорож з іншими, цінність очевидна. Сім'я з 4 осіб платить приблизно стільки ж на особу, як за окремі звичайні варіанти транспорту.",
    blogWorthItFaq2Q: "Коли приватний трансфер НЕ вартий?",
    blogWorthItFaq2A: "Одинокі бюджетні мандрівники на коротких відстанях вдень можуть знайти звичайний транспорт економнішим. Однак для нічних прильотів, сімей або груп приватний трансфер майже завжди пропонує кращу цінність.",
    blogWorthItFaq3Q: "Наскільки дорожчий приватний трансфер?",
    blogWorthItFaq3A: "Приватні трансфери зазвичай коштують у 2-3 рази більше звичайного тарифу. Однак це включає зустріч, фіксовану ціну, преміум-авто та професійного водія. Для 2+ пасажирів вартість на особу стає порівнянною.",
    blogWorthItFaq4Q: "Що робить приватний трансфер кращим за звичайний транспорт?",
    blogWorthItFaq4A: "Ключові переваги: попереднє бронювання без очікування, фіксована ціна без сюрпризів, зустріч з табличкою, професійний англомовний водій, преміум-авто, моніторинг рейсів та доставка від дверей до дверей.",
    blogWorthItFaq5Q: "Чи безпечно бронювати приватний трансфер онлайн?",
    blogWorthItFaq5A: "Так, з надійними компаніями. Зверніть увагу на: відгуки, прозорі ціни, професійний сайт, зв'язок через WhatsApp та підтвердження даних водія перед зустріччю.",
    blogWorthItFaq6Q: "Чи може приватний трансфер прийняти велику групу?",
    blogWorthItFaq6A: "Так! Ми пропонуємо автомобілі від седанів (до 3 осіб) до мінівенів (до 8) та мікроавтобусів (до 16). Великі групи часто отримують найкращу ціну на особу з приватним трансфером.",
